"""
Central configuration for the Soybean Yield Prediction backend.

MODEL_FACTORY_DIR points at the `model_factory` folder that the *training* pipeline
produces. That folder is expected to be placed here manually (it is NOT generated by
this repo), keeping the exact structure created by the training notebook:

    model_factory/
        <run_tag>/                      e.g. weeks_14_20, weeks_14_30 ...
            <ModelName>/                e.g. XGBoost, LightGBM, CatBoost, Stacking_Ensemble
                model.joblib
                region_encoder.joblib
                imputer.joblib
                cluster_artifacts.joblib
                feature_schema.json

Override the location via the MODEL_FACTORY_DIR environment variable if you keep the
folder somewhere other than the repo root.
"""

import os
from pathlib import Path

BASE_DIR = Path(__file__).resolve().parent.parent

# Where the manually-placed model_factory folder lives.
MODEL_FACTORY_DIR = Path(os.environ.get("MODEL_FACTORY_DIR", BASE_DIR / "model_factory"))

MODEL_FACTORY_DIR_CORN = Path(os.environ.get("MODEL_FACTORY_DIR", BASE_DIR / "model_factory_corn"))



# CORS: allow the Streamlit frontend (and any other origin) to call this API.
# Override with a comma-separated list via the CORS_ORIGINS env var in production.
CORS_ORIGINS = os.environ.get("CORS_ORIGINS", "*")

# API metadata
API_TITLE = "Soybean Yield Prediction API"
API_DESCRIPTION = (
    "Backend inference service for the soybean yield prediction pipeline. "
    "Phase 1 predicts final harvest yield from raw weekly weather + soil readings. "
    "Phase 2 recommends controllable-factor changes to maximize that predicted yield."
)
API_VERSION = "1.0.0"

# Target unit conversion used throughout the training/inference pipeline
KG_HA_PER_BU_ACRE = 67.25
KG_HA_PER_BU_ACRE_CORN = 62.77